def countDigitOccurrences(nums, digit):
    total = 0
    for x in nums:
        # Peel off the last digit repeatedly (nums[i] >= 1, so x > 0 loop is safe)
        while x > 0:
            if x % 10 == digit:
                total += 1
            x //= 10
    return total
